  },
  State_122442_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>: সজ্জিত করলে <Block:[Block:StateArg1]> শিল্ড এবং <Energy:[Energy:StateArg1]> অ্যালিমাস পাও। টার্নের শেষে, এই নিয়তিচক্র স্বয়ংক্রিয়ভাবে অসজ্জিত হয়ে যায়। পরের বার ড্র পাইল শাফল হলে, এই WoD-টিকে ড্র পাইলে রাখো, এবং 「বাক্সে শৈশবের আনন্দ」 সজ্জিত করার সময় যে অ্যালিমাস ও শিল্ড পাও, তা +[StateArg2]।"
