  State_123109_Desc = {
    Text = "দলে অনন্য: 「D-চিহ্ন」 দোকানে তোমার প্রথম 「প্রার্থনাগাথা」 ক্রয়, অথবা 「ভস্ম ধ্বংসাবশেষ」‑এ তোমার প্রথম ছাড়যুক্ত আইটেম ক্রয়ের ক্ষেত্রে, 0 কালো চিহ্ন খরচ হওয়ার <WeaponEffect_Num:[StateArg1]%> সম্ভাবনা থাকে। প্রতিটি অনুসন্ধানে এটি মাত্র একবারই সক্রিয় হতে পারে।"
  },
  State_123109_WeaponDesc = {
    Text = "「ডি-মার্ক」-এ প্রথমবার「অরিসন」কেনার সময়, অথবা「ভস্মের ধ্বংসাবশেষ」-এ প্রথমবার ছাড়ের পণ্য কেনার জন্য প্রয়োজনীয় কালো মুদ্রার <WeaponEffect_Num:[StateArg1]%> সম্ভাবনা রয়েছে যে তা 0 হয়ে যাবে, প্রতিটি অভিযানে সর্বোচ্চ 1 বার কার্যকর হয়।"
