  State_123177_Desc = {
    Text = "টার্নের শুরুতে পরিষ্কার হয়। 10 স্তর সংখ্যায় পৌঁছানোর পর, পরের বার কোনো কার্ড খেলা হলে, মুশেট সঙ্গে সঙ্গে ক্রিয়া করে, 「অস্থায়ী উন্মত্ততা」 সরিয়ে ফেলে এবং 「মরণ বিস্ফোরণ」 অভিপ্রায়টি যোগ করে।"
