  State_132891_Desc = {
    Text = "<PVPWeaponKeywords:ভাগ্যচক্র>：সজ্জিত অবস্থায় [StateArg1] <StrongEffectKeywords:শক্তি> অর্জন করে，অন্যান্য মিত্রদের উন্মত্ত বিস্ফোরণের পর তাদের <PVPOneMeetingKeywords:একবারের সাক্ষাৎ> প্রদান করে।"
