  State_133353_Desc = {
    Text = "<PVPWeaponKeywords:ভাগ্যচক্র>：সজ্জিত করার পর, সজ্জিতকারীর 「স্ট্রাইক」, 「দক্ষতা」, 「উন্মত্ততা বিস্ফোরণ」 বিবরণ শনাক্ত করা যায় না, কিন্তু প্রতিটি ক্ষতি, ঢাল, নিরাময় এলোমেলোভাবে [StateArg1]％～[StateArg2]％ বৃদ্ধি পায়।"
  },
  State_133353_Name = {
    Text = "কাদায় রূপকথা"
  },
  State_133354_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>：এই নিয়তিচক্র মৃত্যুর পরে ধরে রাখো। সজ্জিতকারী মৃত্যুর সময় এবং মৃত্যু অবস্থায় পরবর্তী [Layer] রাউন্ড শেষে, অন্যান্য বন্ধুপক্ষ <Heal:[Heal:StateArg1]> <PVPFeatheredSeedsKeyWords:পালক বীজ> এবং জীবন লাভ করে।"
