  },
  State_133369_Name = {
    Text = "রৌপ্য চাবির দ্বার অতিক্রম"
  },
  State_133372_Desc = {
    Text = "যদি বর্তমানে অতিমাত্রা পালে থাকে, তাহলে সিঙ্গুলারিটি লিপ প্রভাব সক্রিয় হয়। 「সিঙ্গুলারিটি অ্যানিহিলেশন」-ও এই পালে পরবর্তী সিঙ্গুলারিটি লিপ অবশ্যই সক্রিয় করতে পারে।"
  },
  State_133372_Name = {
    Text = "<SingularityKeywords:সিঙ্গুলারিটি লিপ>"
  },
  State_133391_Desc = {
    Text = "যদি এই অবস্থার স্তর সংখ্যা লক্ষ্যের জীবনীশক্তির সমান বা বেশি হয়, তাহলে সমস্ত ভাগ্য রায় অপসারণ করে এবং সরাসরি লক্ষ্যকে হত্যা করে। প্রয়োগকৃত নির্দিষ্ট ভাগ্য রায় ক্ষতি শক্তিবৃদ্ধি বোনাস পায়।"
  },
  State_133391_Name = {
    Text = "<CutKeywords:ভাগ্য রায়>"
  },
  State_133395_Desc = {
