  },
  State_133717_Name = {
    Text = "কার্ড বৈশিষ্ট্য প্রচার"
  },
  State_133774_Desc = {
    Text = "প্রতিটি স্তরের জন্য এই কার্ডের ক্ষতি, নির্দিষ্ট শক্তি ও তাঁবু ক্ষতি বৃদ্ধি, নির্দিষ্ট বিষক্রিয়া, নির্দিষ্ট পাল্টা আঘাতের চূড়ান্ত প্রভাব ২% বৃদ্ধি পায়；নির্দিষ্ট শিল্ড, নির্দিষ্ট জীবন নিরাময়, STR▼-এর চূড়ান্ত প্রভাব ১% বৃদ্ধি পায়। সিঙ্গুলারিটি বীকনযুক্ত কার্ড 「মাত্রা পরিভ্রমণ」 সক্রিয় করতে পারে না।"
  },
  State_133774_Name = {
    Text = "<SingularityKeywords1:সিঙ্গুলারিটি বীকন>"
  },
  State_133775_Desc = {
    Text = "প্রতিটি স্তরের জন্য সকল জাগরণকারী কার্ডের ক্ষতি, নির্দিষ্ট শক্তি ও তাঁবু ক্ষতি বৃদ্ধি, নির্দিষ্ট বিষক্রিয়া, নির্দিষ্ট পাল্টা আঘাতের চূড়ান্ত প্রভাব ২% বৃদ্ধি পায়；নির্দিষ্ট শিল্ড, নির্দিষ্ট জীবন নিরাময়, STR▼-এর চূড়ান্ত প্রভাব ১% বৃদ্ধি পায়।"
  },
  State_133775_Name = {
    Text = "<SingularityKeywords2:সিঙ্গুলারিটি প্রিজম>"
  },
  State_133961_Desc = {
    Text = "দলে একমাত্র：অন্বেষণ শুরুর পর একটি「বসন্তের বার্তা」তৈরি করে ডেকে রাখো：অ্যারিথমেটিকা ব্যয় ১，<WeaponEffect_Num:[StateArg1]> পয়েন্ট S-শক্তি অর্জন করো，খেলার পর স্থায়ীভাবে「পূর্ণ চেরি ফুল」-এ রূপান্তরিত হয়：অ্যারিথমেটিকা ব্যয় ১，<WeaponEffect_Num:[StateArg2]> পয়েন্ট S-শক্তি অর্জন করো，খেলার পর স্থায়ীভাবে「হানাফুবুকি」-তে রূপান্তরিত হয়：অ্যারিথমেটিকা ব্যয় ১，<WeaponEffect_Num:[StateArg3]> পয়েন্ট S-শক্তি অর্জন করো，খেলার পর স্থায়ীভাবে「একবারের সাক্ষাৎ」-এ রূপান্তরিত হয়：অ্যারিথমেটিকা ব্যয় ১，আনলক করা ৩টি র‍্যান্ডম পসি থেকে ১টি বেছে তাৎক্ষণিকভাবে মুক্তি দাও এবং ২ বার কার্যকর করো，খেলার পর স্থায়ীভাবে「বসন্তের বার্তা」-তে রূপান্তরিত হয়。এই কার্ডগুলো সবই「ধরে রাখো」বৈশিষ্ট্য রাখে।"
  },
  State_133961_WeaponDesc = {
    Text = "অনুসন্ধান শুরুর পর একটি 「বসন্তের চিঠি」 কার্ড তৈরি করে ডেকে রাখে: কম্পিউটিং পাওয়ার খরচ 1, <WeaponEffect_Num:[StateArg1]> পয়েন্ট সিলভার কী এনার্জি অর্জন করে, খেলার পর স্থায়ীভাবে 「পূর্ণ প্রস্ফুটন」-এ রূপান্তরিত হয়: কম্পিউটিং পাওয়ার খরচ 1, <WeaponEffect_Num:[StateArg2]> পয়েন্ট সিলভার কী এনার্জি অর্জন করে, খেলার পর স্থায়ীভাবে 「পুষ্পবৃষ্টি」-তে রূপান্তরিত হয়: কম্পিউটিং পাওয়ার খরচ 1, <WeaponEffect_Num:[StateArg3]> পয়েন্ট সিলভার কী এনার্জি অর্জন করে, খেলার পর স্থায়ীভাবে 「একবারের সাক্ষাৎ」-এ রূপান্তরিত হয়: কম্পিউটিং পাওয়ার খরচ 1, আনলক করা 3টি র‍্যান্ডম কী-অর্ডার থেকে 1টি বেছে তৎক্ষণাৎ মুক্ত করে এবং 2 বার কার্যকর হয়, খেলার পর স্থায়ীভাবে 「বসন্তের চিঠি」-তে রূপান্তরিত হয়। এই সকল কার্ডে 「সংরক্ষণ」 রয়েছে।"
