  State_143573_Desc = {
    Text = "দুঃস্বপ্নের বন্দী হলো পন্টোসের বাফ কার্ড যা 「অপহরণের দুঃস্বপ্ন」「উপদ্রবের দুঃস্বপ্ন」「হত্যার দুঃস্বপ্ন」 অন্তর্ভুক্ত করে, মোট 3 ধরনের। স্থায়ী 「বন্দী দুঃস্বপ্ন」 তৈরি করার সময় যদি স্থায়ী 「বন্দী দুঃস্বপ্ন」 6টির বেশি হয়, তাহলে একটি এলোমেলো স্থায়ী 「বন্দী দুঃস্বপ্ন」কে অ্যারিথমেটিকা ব্যয় +1 কিন্তু অতিরিক্ত 1 বার কার্যকর হওয়া 「যমজ বন্দী দুঃস্বপ্ন」তে আপগ্রেড করা হবে, 「যমজ বন্দী দুঃস্বপ্ন」 ডেকে 2টি 「বন্দী দুঃস্বপ্ন」 হিসেবে গণ্য হয়। যদি সব 「বন্দী দুঃস্বপ্ন」 ইতিমধ্যে আপগ্রেড হয়ে গিয়ে থাকে, তাহলে <DestructionKeywords:ধ্বংস> সহ 1টি 「উন্নত অন্তর্দৃষ্টি」 হাতে রাখুন।"
  },
  State_143573_Name = {
