  },
  State_143595_Name = {
    Text = "কালো রাজহাঁসের নৃত্য"
  },
  State_143597_Desc = {
    Text = "দলে একমাত্র：সজ্জিতকারী কর্তৃক প্রদত্ত STR▼ প্রভাব <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়। 「প্রচণ্ড তরঙ্গ」 ভঙ্গিতে পরিবর্তন করলে অস্থায়ী ক্রিটিক্যাল ক্ষতি বৃদ্ধি পায়, বৃদ্ধির পরিমাণ নিজের মূল ক্রিটিক্যাল ড্যামেজের <WeaponEffect_Num:[StateArg1]%> এর সমান, 3 রাউন্ড কুলডাউন।"
  },
  State_143597_WeaponDesc = {
    Text = "সজ্জিতকারী কর্তৃক প্রদত্ত STR▼ প্রভাব <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়। 「প্রচণ্ড তরঙ্গ」 ভঙ্গিতে পরিবর্তন করার পরে অস্থায়ী ক্রিটিক্যাল ক্ষতি <WeaponEffect_Num:[DescArg1]%> বৃদ্ধি পায়, 3 রাউন্ড কুলডাউন।"
  },
  State_143598_Desc = {
    Text = "দলে একমাত্র：সজ্জিতকারী কর্তৃক প্রদত্ত STR▼ প্রভাব <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়, প্রতি 1 জন শত্রু হত্যা করলে এই অভিযানে রাউন্ড শেষে সজ্জিতকারীর নির্দিষ্ট নিরাময় অ্যালিমাস 2 পয়েন্ট বৃদ্ধি পায়, সর্বোচ্চ <WeaponEffect_Num:[StateArg2]> বার স্তুপ করা যায়। 「প্রচণ্ড তরঙ্গ」 ভঙ্গিতে পরিবর্তন করার পরে অস্থায়ী ক্রিটিক্যাল ক্ষতি বৃদ্ধি পায়, বৃদ্ধির পরিমাণ নিজের মূল ক্রিটিক্যাল ড্যামেজের <WeaponEffect_Num:[StateArg1]%> এর সমান, 3 রাউন্ড কুলডাউন।"
  },
  State_143598_WeaponDesc = {
    Text = "সজ্জিতকারী STR▼ প্রভাব <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি করে, প্রতি 1টি শত্রু হত্যায় সজ্জিতকারীর এই অন্বেষণ রাউন্ড শেষে নির্ধারিত নিরাময় অ্যালিমাস 2 পয়েন্ট বৃদ্ধি পায়, সর্বোচ্চ <WeaponEffect_Num:[StateArg2]> বার স্তূপ করা যায়। 「প্রচণ্ড তরঙ্গ」ভঙ্গিতে পরিবর্তনের পরে অস্থায়ী ক্রিটিক্যাল ক্ষতি <WeaponEffect_Num:[DescArg1]%> বৃদ্ধি পায়, 3 রাউন্ড কুলডাউন।"
  },
  State_143683_Desc = {
    Text = "এই জাগরণকারীর পশ্চাদ্ধাবন সিলমোহরের কারণে ব্যবহার করা যাচ্ছে না, [Layer] রাউন্ড পরে সিলমোহর উন্মুক্ত হবে।"
