  },
  State_144381_Name = {
    Text = "<Yishiganshe:চেতনা হস্তক্ষেপ>"
  },
  State_144441_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>：বন্ধু মারা গেলে, নিজে <Energy:[Energy:StateArg1]> অ্যালিমাস অর্জন করে। বন্ধু পুনরুত্থিত হলে, সে <Energy:[Energy:StateArg2]> অ্যালিমাস অর্জন করে। অ্যালিমাস অর্জনের প্রভাব কেবল তখনই কার্যকর হয় যখন লক্ষ্যের অ্যালিমাস পূর্ণ না থাকে, আরও [Layer] বার কার্যকর হবে, গণনা শেষ হলে এই নিয়তিচক্র ধ্বংস হবে।"
  },
  State_144441_Name = {
    Text = "আত্মা সমন্বয়"
  },
  State_144494_Desc = {
    Text = "মোট 7 ধরনের প্রভাব রয়েছে, যার মধ্যে রয়েছে: 8টি কার্ড ড্র, 6 পয়েন্ট অ্যারিথমেটিকা অর্জন, S-শক্তি অর্জন, সকল জাগরণকারী নির্দিষ্ট অ্যালিমাস অর্জন, শক্তি অর্জন, অস্থায়ীভাবে সকল শত্রুর শক্তি হ্রাস, অস্থায়ীভাবে ক্ষতি বর্ধন বৃদ্ধি।"
  },
  State_144494_Name = {
    Text = "<Blessing:উপহার>"
  },
  State_144508_Desc = {
    Text = "「মূল্য」মোট 3 ধরনের, যার মধ্যে রয়েছে 「সুযোগ হাতছাড়া」、「অতিরঞ্জিত কথা」、「গোপন হত্যার ফাঁদ」。\n「সুযোগ হাতছাড়া」：2 রাউন্ড পরে 「উপহার」 প্রভাব অর্জন করুন।\n「অতিরঞ্জিত কথা」：「উপহার」 প্রভাব 50％ হ্রাস পায়।\n「গোপন হত্যার ফাঁদ」：নিজেকে এলোমেলোভাবে 1 ধরনের ভিন্ন প্রভাব দেয়: 2 রাউন্ড দুর্বলতা、2 রাউন্ড ভঙ্গুর、2 রাউন্ড ব্লাইটেন、নিজের সর্বোচ্চ জীবনী শক্তির 1% সমান বিষক্রিয়া、2 স্তর শূন্যতা、হাতের এলোমেলো 2টি কার্ডে 1 স্তর স্থবিরতা আরোপ、2টি অস্থায়ী উপসর্গ কার্ড তৈরি করুন (যুদ্ধ পেরিয়ে উত্তরাধিকার হয় না) ড্র পাইলের শীর্ষে রাখুন।"
  },
  State_144508_Name = {
    Text = "<BlessingNegativeEffect:মূল্য>"
  },
  State_144519_Desc = {
    Text = "পরীক্ষামূলক প্রক্রিয়া পরিমাণ, রাউন্ড শুরুর পরে বা কার্ড খেলার পরে রিফ্রেশ হয়। বর্তমানে [Layer] টি বাউন্ডারি স্পিরিট রয়েছে।"
  },
  State_144519_Name = {
    Text = "নতুন কেওস রিয়েল্ম এলিট"
  },
  State_145228_Name = {
    Text = "<WormGrowth:তৃপ্তিভোজ>"
  },
  State_145229_Desc = {
    Text = "তুমিও আশীর্বাদের একটি অংশ~। কারাবুর এক্সাল্ট দ্বারা ব্যবহার করে বোনাস পাওয়া যায়, এই অবস্থা সর্বোচ্চ 5 স্তর পর্যন্ত জমা হতে পারে। যুদ্ধ শেষে পরিষ্কার হয় না"
  },
  State_145229_Name = {
    Text = "<SacrificialMark:উৎসর্গ>"
  },
  State_145436_Desc = {
