  },
  State_145437_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>：সজ্জিত করার সময় [StateArg2] স্তর <EnergyStorageKeywords:চার্জ> অর্জন করুন, 「আঘাত」 ক্ষতি বৃদ্ধি [StateArg1]% এবং <PVPPunctureDamagewords:ভেদন ক্ষতি>-তে পরিবর্তিত হয়।"
