  },
  State_145698_Name = {Text = "লক"},
  State_145699_Desc = {
    Text = "·লক করা <StatusApplier:>কে অগ্রাধিকার দিয়ে আক্রমণ করে, একক লক্ষ্য নির্বাচনের সময় শুধুমাত্র লক করা লক্ষ্য বেছে নেওয়া যাবে, উপহাস এবং লুকানো উপেক্ষা করে।\n·নিজে মৃত্যুর পর <StatusApplier:> 「<PVPDerivativeCardKeywords_32:যুদ্ধে আসো!>」 অর্জন করে।"
  },
  State_145699_Name = {Text = "লক"},
  State_145709_Desc = {
    Text = "প্রতিটি স্তর কারাবুর CON-এর 10% সমান জীবন সীমা বৃদ্ধি করে, 「পেট ভরে খাওয়া」 সর্বোচ্চ 50 স্তর পর্যন্ত জমা হতে পারে। এই অবস্থা অর্জনের সময় যদি সীমায় পৌঁছানো থাকে, তাহলে প্রতিটি অতিরিক্ত স্তরের পরিবর্তে সমপরিমাণের 3 গুণ জীবন নিরাময় হয়। প্রতিটি বস যুদ্ধ-বহির্ভূত যুদ্ধে সর্বোচ্চ 10 স্তর 「পেট ভরে খাওয়া」 অর্জন করা যায়। যুদ্ধ শেষে মুছে যায় না।"
  },
  State_145709_Name = {
    Text = "<WormGrowth:তৃপ্তিভোজ>"
  },
  State_145710_Desc = {
