  },
  State_146041_Desc = {
    Text = "এই জাগরণকারী মনে করে সে পার্থিব কোলাহল থেকে বিচ্ছিন্ন হয়ে গেছে।\n·রাউন্ড শেষ হওয়ার আগে কোনো অ্যাকশন করা যাবে না, ৯৯% ক্ষতি হ্রাস পাবে, এবং লক্ষ্যের প্রতিরোধ না থাকলে লক্ষ্য প্রতিরোধ অর্জন করবে।\n·প্রভাব শেষ হলে সকল বন্ধুপক্ষের উপর <Damage:[Layer]> বিশুদ্ধ ক্ষতি প্রদান করে।\n·প্রয়োগের সময় লক্ষ্যের প্রতিরোধ থাকলে, ধোঁকা তাৎক্ষণিকভাবে শেষ হয় এবং লক্ষ্যের উপর ক্ষতি দ্বিগুণ হয়।"
