  },
  State_24211_Desc = {
    Text = "\nটার্ন শেষে, সামনের সারির শত্রুদের উপর [DescArg4] বার [DescArg2] ক্ষতি প্রয়োগ করো। যদি কোনো শত্রু নিহত হয়, তবে ক্ষতি [DescArg3] পয়েন্ট করে বৃদ্ধি পায়, সর্বোচ্চ 5 বার পর্যন্ত(বর্তমানে [DescArg6] বার)।\nপ্রতিবার জাগরণকারী Exalt ব্যবহার করলে, এই টার্নে অতিরিক্ত একবার আক্রমণ সূচিত হবে।\nরক্ষক Posse ব্যবহার করার পর, এই টার্নে আক্রমণের লক্ষ্য সব শত্রুতে পরিবর্তিত হবে। যদি এটি বস যুদ্ধ হয়, তবে 「দিব্য অঙ্গ」 দ্বারা প্রদত্ত ক্ষতিও অতিরিক্ত [DescArg5] পয়েন্ট বৃদ্ধি পাবে।"
