  State_2500_Name = {Text = "বিষ"},
  State_2501_Desc = {
    Text = "দলে অনন্য: দলের সর্বোচ্চ HP 10% বৃদ্ধি পায়। ধারণকারীর প্রদত্ত নিরাময় এবং চরিত্রের ঢাল <WeaponEffect_Num:[StateArg3]%> বৃদ্ধি পায়। ধারণকারীর 「স্ট্রাইক」 ব্যবহার করার পর, হারানো HP-এর <WeaponEffect_Num:[StateArg1]%> পুনরুদ্ধার করুন। ধারণকারীর 「ডিফেন্স」 ব্যবহার করার পর, বর্তমান জীবনের <WeaponEffect_Num:[StateArg2]%>-এর সমান চরিত্রের ঢাল অর্জন করুন। এই প্রভাব প্রতি টার্নে সর্বোচ্চ 1 বার করে সক্রিয় হতে পারে।"
