    Text = "দলে একমাত্র：অন্বেষণ শুরু হওয়ার পর, সজ্জিতকারী রূপালি কড মৎস্যমানব সত্তার অবস্থায় প্রবেশ করে। সজ্জিতকারী এক্সাল্ট ব্যবহার করার পর রূপালি কড মৎস্যমানব সত্তা এবং বিড়াল সত্তার মধ্যে পরিবর্তন হবে।\nরূপালি কড মৎস্যমানব সত্তা：সজ্জিতকারী সক্রিয় ক্ষতি করার পর <WeaponEffect_Num:[StateArg1]> S-শক্তি অর্জন করে। বিড়াল সত্তা：সজ্জিতকারী সক্রিয় ক্ষতি করার পর, সজ্জিতকারীর অস্থায়ী ক্রিটিক্যাল ক্ষতি <WeaponEffect_Num:+[StateArg2]%>। এই দুটি প্রভাব প্রতি রাউন্ডে সর্বোচ্চ ৫ বার সক্রিয় হওয়ার সুযোগ ভাগ করে নেয়।"
