    Text = "ধারণকারীর দ্বারা সৃষ্ট চরিত্রের ঢাল উৎপাদন প্রভাব <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়। পসি মুক্ত করার পর, সব জাগরণকারী <WeaponEffect_Num:[StateArg2]%> অস্থায়ী ক্রিটিক্যাল হার এবং ক্রিটিক্যাল ক্ষতি পায়, তবে [DescArg1] উৎসর্গ অর্জন করে। বর্তমান রাজ্য যদি 「Aequor」 হয়, তবে পসি মুক্ত করলে শুঁড় ক্ষতিও [DescArg2] বৃদ্ধি পায়।"
