  State_57767_Desc = {
    Text = "<PVPWeaponKeywords:Wheel of Destiny>: টার্নের শেষে, <Energy:[Energy:StateArg1]> অ্যালিমাস কমিয়ে দাও এবং একটি <PVPDerivativeCardKeywords_12:\"Tiny Wish\"> লাভ করো। যদি কমানোর মতো যথেষ্ট অ্যালিমাস না থাকে, তবে তার বদলে <Energy:[Energy:StateArg2]> অ্যালিমাস লাভ করো।"
  },
  State_57767_Name = {
