  State_57768_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>: 「দক্ষতা」 ক্ষতি +[StateArg1]%। 「Exalt」‑এর পর হারানো HP‑এর [StateArg2]% পুনরুদ্ধার করো।"
