  State_57768_Name = {
    Text = "তুষার পর্বত গলনের কাল"
  },
  State_57769_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>: ধারণকারী একটি দক্ষতা কার্ড ব্যবহারের পর, ধারণকারীর একটি দক্ষতা কার্ড ড্র করো। এই প্রভাব প্রতি টার্নে মাত্র একবার সক্রিয় হতে পারে।"
