  State_58259_Desc = {
    Text = "Team Unique: ধারণকারীর ক্রিটিক্যাল হার <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়। শত্রু হত্যা করলে <WeaponEffect_Num:[StateArg2]>টি কালো চিহ্ন লাভ করা যায়, অনুসন্ধানের সময় সর্বোচ্চ 3 বার পর্যন্ত। 3 বার সক্রিয় হওয়ার পর, বাকি পুরো অনুসন্ধানের জন্য ধারণকারীর ক্রিটিক্যাল হার স্থায়ীভাবে <WeaponEffect_Num:[StateArg3]%> বৃদ্ধি পায়।"
  },
  State_58259_WeaponDesc = {
    Text = "ধারকের Crit. Rate + <WeaponEffect_Num:[StateArg1]%>। ধারক শত্রু হত্যা করার পর <WeaponEffect_Num:[DescArg2]> কালো চিহ্ন লাভ করে, প্রতি অনুসন্ধানে সর্বোচ্চ 3 বার পর্যন্ত ([DescArg1]/3)। 3 বার সক্রিয় হওয়ার পর, চলতি অনুসন্ধানের জন্য ধারক স্থায়ীভাবে <WeaponEffect_Num:[StateArg3]%> Crit. Rate লাভ করে।"
  },
  State_58297_Desc = {
    Text = "লেক শত্রু হত্যা করলে [DescArg3] ব্ল্যাক মার্ক অর্জন করে, প্রতি অনুসন্ধানে সর্বাধিক 5 বার কার্যকর হয়। ([DescArg1]/5)\nযুদ্ধের মাধ্যমে 50/125/250 ব্ল্যাক মার্ক অর্জনের পর, সৃষ্টির সীমা 1 বৃদ্ধি পায়, যুদ্ধ শেষে একটি 「বিশৃঙ্খলার উত্তরাধিকার」 বেছে সৃষ্টি তালিকায় যোগ করুন। (অর্জিত [DescArg2] পয়েন্ট ব্ল্যাক মার্ক)"
  },
  State_58297_Name = {
    Text = "বিজয়ী সব নেয়"
  },
  State_58447_Desc = {
    Text = "নিম্নলিখিত তিনটি সৃষ্টি অন্তর্ভুক্ত:\n「লাকি উইন্ডব্রেকার」: সকল জাগ্রত সত্তার ক্রিটিক্যাল হিট রেট 10% বৃদ্ধি পায়। সকল লেক ও ডাইসের র‍্যান্ডম ফলাফলে সর্বনিম্ন মান আসবে না।\n<TentacleInjurieIconKeywords:আপগ্রেড>: ক্রিটিক্যাল হিট রেট বৃদ্ধি 15% হয়, এবং র‍্যান্ডম ফলাফলের সর্বোচ্চ মান 1 বৃদ্ধি পায়।\n「বায়াসড ডাইস」: প্রতিবার কী কমান্ড ব্যবহারের পর, হাতে 1টি 「<C05_yansheng1:বায়াসড ডাইস>」 যোগ হয়।\n<TentacleInjurieIconKeywords:আপগ্রেড>: পরিবর্তে হাতে 1টি 「<C05_yansheng2:উজ্জ্বল বায়াসড ডাইস>」 যোগ হয়।\n「বিগমাউথ বাটন」: টার্ন শুরুতে এবং লেক বা ডাইসের র‍্যান্ডম ইফেক্ট ট্রিগার হলে, 50 সিলভার কী এনার্জি ও 2% ক্রিটিক্যাল ড্যামেজ অর্জন করে, সর্বোচ্চ 30% ক্রিটিক্যাল ড্যামেজ পর্যন্ত।\n<TentacleInjurieIconKeywords:আপগ্রেড>: পরিবর্তে 100 সিলভার কী এনার্জি ও 4% ক্রিটিক্যাল ড্যামেজ অর্জন করে, সর্বোচ্চ 50% ক্রিটিক্যাল ড্যামেজ পর্যন্ত।"
  },
