  State_71154_Desc = {
    Text = "টার্নের শুরুতে, আইজিস 15 অ্যালিমাস পায়। আইজিস যখন দুর্বল অবস্থার শত্রুকে ক্ষতি করে, সে তাদের অস্থায়ী STR থেকে 10 চুরি করে, প্রতি টার্নে সর্বোচ্চ 5 বার পর্যন্ত এই প্রভাব কার্যকর হয়।"
  },
  State_71155_Desc = {
    Text = "টার্নের শুরুতে, লেই 15 আলিয়েমাস পায়। প্রতিবার সে HP হারালে, সে 8 শক্তি পায়, যা প্রতি যুদ্ধে সর্বোচ্চ 10 বার পর্যন্ত সঞ্চিত হতে পারে। 10 বার সঞ্চিত হওয়ার পর, 「যন্ত্রণা ও আনন্দ」-এর অ্যারিথমেটিকা ব্যয় 1 হয়, এবং এর ক্ষতির গণনা 1 বৃদ্ধি পায়।"
