  State_71158_Desc = {
    Text = "টার্নের শুরুতে, ডল 15 অ্যালিমাস পায়। যুদ্ধ শুরু হওয়ার পর, ডলের 「Equivalent Exchange」-এর অ্যারিথমেটিকা ব্যয় 0 নির্ধারণ করো। এটি একবার খেলা হলে, পরের টার্নে অতিরিক্ত 2টি কার্ড ড্র করো।"
  },
  State_71159_Desc = {
