  },
  State_71162_Desc = {
    Text = "টার্ন শুরুর সময়, গোলিয়াথ 15 আলিয়েমাস পায়। যদি গোলিয়াথ 1 টার্নের মধ্যে 3 বার ক্ষতি করে, তবে এই যুদ্ধে গোলিয়াথের করা ক্ষতিতে অতিরিক্ত 1x STR বোনাস যুক্ত হয়, যার কুলডাউন 3 টার্ন।"
  },
  State_71163_Desc = {
