  },
  State_71181_Desc = {
    Text = "রাউন্ড শুরুতে সোরেল 15 উন্মত্ত শক্তি অর্জন করে। সোরেল প্রতিবার 1 বার ক্ষতি করলে ভ্রূণ সংমিশ্রণ+10, প্রতি রাউন্ডে সর্বোচ্চ 10 বার কার্যকর হয়। 10 বার কার্যকর হওয়ার পর সোরেলের এই যুদ্ধে ক্রিটিক্যাল ক্ষতি+ 20%।"
  },
  State_71182_Desc = {
    Text = "টার্নের শুরুতে, হ্যামেলন 15 অ্যালিমাস অর্জন করে। 「আত্মা ওভারচার」-এর অ্যারিথমেটিকা ব্যয় 1 কমে যায়, এবং মূল ক্ষতির গণনা 1 বৃদ্ধি পায়।"
  },
  State_71183_Desc = {
    Text = "টার্নের শুরুতে, থাইস 15 অ্যালিমাস পায়। এক টার্নে 3টি কমান্ড কার্ড খেলার পর, থাইস 1টি 「পবিত্রতার উত্তরাধিকারী」 এবং 72 অস্থায়ী STR পায়, যার কুলডাউন 3 টার্ন।"
  },
  State_71187_Desc = {
    Text = "টার্নের শুরুতে, সেলেস্ট 15 আলিয়েমাস পায়। টার্ন শেষ হওয়ার আগে, হাতে থাকা সেলেস্টের প্রতিটি কমান্ড কার্ডের জন্য, 1টি শুঁড় একটি শত্রুকে আক্রমণ করে এবং 8 HP পুনরুদ্ধার করে।"
  },
  State_71188_Desc = {
    Text = "টার্নের শুরুতে, মারফি 15 অ্যালিমাস পায়। মারফির 「আঘাত」 এবং 「প্রতিরক্ষা」 25% 「উৎসর্গ」কে অস্থায়ী শুঁড় ক্ষতিতে রূপান্তর করতে পারে, তবে প্রতি টার্নে একবারই কার্যকর হতে পারে।"
  },
  State_71189_Desc = {
    Text = "টার্নের শুরুতে, নিম্ফিয়া 15 আলিয়েমাস পায়। নিম্ফিয়ার 「Strike」 ব্যবহার করার পর, এই যুদ্ধে 「নিম্ফিয়া」 যে Poison প্রয়োগ করে তা 20% বৃদ্ধি পায়। নিম্ফিয়ার 「Defense」 ব্যবহার করার পর, সব শত্রুর ওপর 50% Poison ট্রিগার হয়। প্রতিটি প্রভাব প্রতি টার্নে সর্বোচ্চ একবার কার্যকর হতে পারে।"
  },
  State_71190_Desc = {
    Text = "টার্নের শুরুতে, ওজিয়ার 15 অ্যালিমাস পায়। প্রতি টার্নে প্রথমবার ওজিয়ার 「ভেদনকারী আঘাত」 বা 「Strike」 ব্যবহার করার পর, সেই টার্নে ওজিয়ার যে Shield এবং STR সৃষ্টি করে তা +50% বৃদ্ধি পায়।"
  },
  State_71191_Desc = {
    Text = "টার্নের শুরুতে, রাইকার 15 অ্যালিমাস পায়। প্রতি টার্নে প্রথম ডাই রোলের ফলাফল সবসময় 6 হবে।"
  },
  State_71192_Desc = {
    Text = "টার্নের শুরুতে, পরিক্রমা·রামোনা 15 অ্যালিমাস পায়। প্রতি টার্নে প্রথমবার 「Loop」 সক্রিয় হলে, 500 কীফ্লেয়ার এবং 1 স্তর 「নেগেনট্রপি」 অর্জন করো।"
  },
  State_71193_Desc = {
    Text = "টার্নের শুরুতে, তুলু 15 অ্যালিমাস পায়। তুলুর জন্য অ্যালিমাস ব্যয় 10 পয়েন্ট কমে যায়, এবং এক্সাল্ট মুক্ত করার পরই তাৎক্ষণিকভাবে 2টি অস্থায়ী শুঁড় সৃষ্টি হয়।"
  },
  State_71194_Desc = {
    Text = "টার্নের শুরুতে, ক্যারেন 15 অ্যালিমাস অর্জন করে। 「নীরব আনুগত্য」 ব্যবহার করলে নিঃশেষিত অ্যারিথমেটিকার দ্বিগুণ ফেরত পাওয়া যাবে, যার কুলডাউন 3 টার্ন।"
  },
  State_71271_Desc = {
    Text = "টার্নের শুরুতে, হোরলা 15 অ্যালিমাস অর্জন করে। যুদ্ধে প্রবেশের শুরুতে, সব আবেগের জন্য 1 স্তর 「রূপক」 লাভ করে। 「রূপক」 প্রভাব +50%।"
  },
  State_71272_Desc = {
    Text = "টার্নের শুরুতে, জেনকিন 15 অ্যালিমাস পায়, এবং চূড়ান্ত ক্ষতি 5% বৃদ্ধি পায়। 「গেট 'এম! ব্রাউন!」-এর মূল ক্ষতি এবং ক্ষতি বৃদ্ধির হার 200% বৃদ্ধি পায়।"
  },
  State_71273_Desc = {
    Text = "টার্নের শুরুতে, ড্যাফোডিল 15 আলিয়েমাস এবং 1টি 「Insight」 পায়। যখনই সে 「Heterogeneous Tide」 খেলে, এই অনুসন্ধান চলাকালীন অর্জিত শক্তি স্থায়ীভাবে 25% করে বৃদ্ধি পায়, সর্বোচ্চ 300% পর্যন্ত।"
  },
  State_71274_Desc = {
