  State_74771_Desc = {
    Text = "একটি এক্সাল্ট সক্রিয় করতে যে পরিমাণ অ্যালিমাস প্রয়োজন।"
  },
  State_74771_Name = {
    Text = "অ্যালিমাস সীমা"
  },
  State_74788_Desc = {
    Text = "\nঅস্তিত্বের প্যারাডক্স: অনুসন্ধানের শুরুতে, মৃত্যু প্রতিরোধের 75% সর্বোচ্চ HP বোনাসে রূপান্তরিত হয়; সর্বোচ্চ 300% মৃত্যু প্রতিরোধ পর্যন্ত রূপান্তর করা যায়, যার ফলে সর্বোচ্চ HP সর্বোচ্চ 10% পর্যন্ত বৃদ্ধি পায়। প্রতি বার মৃত্যু প্রতিরোধ সক্রিয় হলে, অতিরিক্ত একটি 「রৌপ্য চাবির মৃদু আলো」 হাতে যোগ হয়। \nঅতলান্ত ক্ষতচিহ্ন: বস যুদ্ধে, আমাদের পক্ষ যে চিকিৎসা পায়, তা দিয়ে HP সীমার প্রতি 100% পূর্ণ হলেই পরবর্তী চিকিৎসা প্রভাব 25% কমে যায়, কিন্তু মোট মৃত্যু প্রতিরোধ 25% বৃদ্ধি পায়; সর্বোচ্চ 3 বার পর্যন্ত সক্রিয় হতে পারে। \nপ্রিজম্যাটিক লেন্স: টার্নের শুরুতে, যদি কাউন্টার HP সীমার 750% অতিক্রম করে, অতিরিক্ত স্তরগুলো অর্ধেকে নেমে আসে, এবং স্থায়ী কাউন্টার সর্বোচ্চ HP সীমার 2250% পর্যন্ত স্তর সঞ্চয় করতে পারে; যদি শত্রুর বিষ HP সীমার 1000% অতিক্রম করে, অতিরিক্ত স্তরগুলো অর্ধেকে নেমে আসে, এবং বিষ সর্বোচ্চ HP সীমার 3000% পর্যন্ত স্তর সঞ্চয় করতে পারে। দলের প্রতি 4% ক্ষতি বর্ধন বৈশিষ্ট্যের জন্য, উপরের সব সীমা 1% করে বৃদ্ধি পায়। জাগরণকারীর কাউন্টার থেকে প্রাপ্ত ক্ষতি বোনাস 70% কমে যায়, কিন্তু সব বিষ ও কাউন্টারজনিত ক্ষতি 10% বৃদ্ধি পায়। শত্রুর টার্নের শুরুতে, সক্রিয় প্রতিটি নসিসের জন্য বর্তমান স্থায়ী কাউন্টারের 25% অস্থায়ী কাউন্টার হিসেবে পাওয়া যায়, এবং সব শত্রুর ওপর 25% বিষ প্রয়োগ হয়। \nভাগ্যের আলোক শঙ্কু: সাধারণ দানবেরা 「দৃষ্টি」 নিক্ষেপ করতে যে টার্ন নেয়, তা পরিবর্তিত হয়ে 6 টার্ন হয়। সব যুদ্ধের টার্নসীমা 15 টার্ন; তবে 15তম টার্নের শুরুতে হাতে একটি 「আলোক শঙ্কু সীমানা」 যোগ হয়: কীফ্লেয়ার এবং সব জাগরণকারীর আলিয়েমাস সর্বোচ্চ সীমায় পৌঁছে যায়।"
  },
  State_74788_Name = {
    Text = "(সাময়িকভাবে বাতিল)"
  },
  State_74791_Desc = {
    Text = "\n·অ্যারিথমেটিকা সামঞ্জস্য：একক রাউন্ডে ১০টি কমান্ড কার্ড খেলা হলে, প্রতিটি অতিরিক্ত কমান্ড কার্ড খেলার সময় ১ স্তর「অ্যারিথমেটিকা সামঞ্জস্য」অর্জিত হয়।「অ্যারিথমেটিকা সামঞ্জস্য」এই রাউন্ডে প্রতিটি কমান্ড কার্ড খেলার সময় অ্যারিথমেটিকা ব্যয় +১ করে, এভাবে ব্যয়িত প্রতিটি অতিরিক্ত অ্যারিথমেটিকা ১০০% জাগরণকারীর রৌপ্য চাবি রিচার্জের S-শক্তিতে রূপান্তরিত হয়, স্তর যোগ করা যায়। অতিমাত্রিক স্থান সক্রিয় হওয়ার পর, অ্যারিথমেটিকা সামঞ্জস্য প্রভাব রিসেট হয়।\n·গণনাশক্তি পরিপূর্ণ：কার্ড খেলার পর এই রাউন্ডে তার অ্যারিথমেটিকা ব্যয় হ্রাস প্রভাব সরিয়ে দেয়। যুদ্ধে বর্তমান অ্যারিথমেটিকা ১২ ছাড়িয়ে গেলে, অতিরিক্ত প্রতিটি অ্যারিথমেটিকা স্বয়ংক্রিয়ভাবে ৩০০% দলের গড় রৌপ্য চাবি রিচার্জের S-শক্তিতে রূপান্তরিত হয়।\n·উন্মাদনার সমন্বয়：অ্যালিমাস শতাংশ বৃদ্ধির প্রভাব অর্ধেক হয়ে যায়। প্রতিটি জাগরণকারী এক্সাল্ট প্রয়োগের পর তার মৌলিক উন্মত্ততা +১০ হয়। রাউন্ড শেষে প্রতিটি জাগরণকারী যে এক্সাল্ট প্রয়োগ করেনি তার জন্য ২০০％ দলের গড় রৌপ্য চাবি রিচার্জের S-শক্তি অর্জিত হয়।"
  },
  State_74791_Name = {
    Text = "কীফ্লেয়ারের ঐকতান"
