  State_74947_Desc = {
    Text = "<PVPWeaponKeywords:নিয়তিচক্র>：রাউন্ড শুরুতে, <HPAndShieldMin:সর্বনিম্ন জীবন ও শিল্ড> বিশিষ্ট শত্রুর উপর [StateArg1] স্তর অ্যাকশন লক প্রয়োগ করে। সজ্জিতকারী হত্যা করার পরে, অবিলম্বে এই প্রভাব একবার সক্রিয় হয়।"
