  State_74948_Name = {
    Text = "সম্মোহনী দোলক"
  },
  State_76236_Desc = {
    Text = "\n·রৌপ্য চাবির জাগরণ：S-শক্তি পূর্ণ হলে、অতিরিক্তভাবে「রৌপ্য চাবির জাগরণ」বেছে নিয়ে নির্দিষ্ট জাগরণকারীর জাগরণ কার্ড হাতে রাখা যাবে এবং সেটি「ধরে রাখো」অর্জন করবে、এই যুদ্ধের জন্য কার্যকর।「রৌপ্য চাবির জাগরণ」প্রতি রাউন্ডে শুধু ১ বার সক্রিয় হতে পারে、「পসি」থেকে স্বাধীনভাবে কুলডাউন হয়।\n·কীফ্লেয়ার ওভারলোড：「রৌপ্য চাবির জাগরণ」ব্যবহার করার সময়、প্রতিটি আনলক করা জাগরণ সহ জাগরণকারীর জন্য অতিরিক্ত ১০০০ পয়েন্ট S-শক্তি কাটা হবে、এই প্রভাব S-শক্তিকে ঋণাত্মক করতে পারে।\n·সংরক্ষণ খোদাই：রক্ষকের প্রতিটি ১টি পসির জন্য、「বস্তু গবেষণার গভীরতা」ও「আত্মিক জ্ঞান গবেষণার গভীরতা」১％ বৃদ্ধি পাবে、সর্বোচ্চ ৫০％ পর্যন্ত। সমস্ত R নিয়তিচক্রের প্রভাব পরিবর্তিত হয়ে সজ্জিতকারীর মাত্রিক প্রতিচ্ছবি রেলিক আবির্ভূত হওয়ার সম্ভাবনা ১০০% বৃদ্ধি করে।"
  },
  State_76236_Name = {
    Text = "উজ্জ্বল রৌপ্য আভা"
  },
  State_76277_Desc = {
    Text = "দলে অনন্য: বস যুদ্ধ শুরু হওয়ার পর, সর্বোচ্চ 50টি কালো চিহ্ন ব্যয় করুন; প্রতিটি কালো চিহ্ন ব্যয়ে <WeaponEffect_Num:[StateArg1]%> <DeathResistanceIconKeywords:মৃত্যু প্রতিরোধ> প্রদান করা হবে। নাক্ষত্রিক অধ্যায়-এ, এই প্রভাব পরিবর্তিত হয়ে দাঁড়ায়: 「ধারকের মাত্রিক প্রতিচ্ছবি রেলিক আবির্ভূত হওয়ার সম্ভাবনা 100% বৃদ্ধি পায়।」"
  },
  State_76277_WeaponDesc = {
