  State_76434_Desc = {
    Text = "প্রতিবার একটি কমান্ড কার্ড খেলা হলে, যদি অ্যারিথমেটিকা সামঞ্জস্য-এর কারণে অতিরিক্ত অ্যারিথমেটিকা ক্ষয় হয়, তবে জাগরণের ধারকের কীফ্লেয়ার পুনর্জন্মের 100% সমপরিমাণ অতিরিক্ত কীফ্লেয়ার অর্জন করো। এই প্রভাব স্তরায়িত হতে পারে।"
