  State_76529_Desc = {
    Text = "তুলে নেওয়ার সময়, কোনো এক জাগরণকারীর একটি কার্ড বেছে নাও এবং তার অ্যারিথমেটিকা ব্যয় 1 কমাও। সেটি খেলার পর, 1টি কার্ড ড্র করো এবং তাকে 「স্ট্রাইক」 হিসেবে গণ্য করো।"
  },
  State_76533_Desc = {
