  },
  State_77688_Desc = {
    Text = "পঞ্চম টার্নের শুরুতে অথবা আসন্ন মৃত্যুর মুহূর্তে, মৃত্যুর প্রতি অনাক্রম্যতা লাভ করো এবং অভিপ্রায় “যান্ত্রিক উত্থান”-এ রূপান্তরিত করো।"
  },
  State_77688_Name = {
    Text = "দুর্বল দেহ"
  },
  State_77690_Desc = {
    Text = "「আধা-যান্ত্রিক রূপ」-এ স্যুইচ করার পর, প্রতিটি 「Finale」 স্তর অতিরিক্ত 10% Max HP প্রদান করে। 「আধা-যান্ত্রিক রূপ」-এ, 「মেল্টডাউন·ডল」 এর 「Finale」 স্তর যত বাড়বে, সে ততই অধিক ভয়াবহ Skill মুক্ত করবে।"
  },
  State_77690_Name = {
    Text = "অন্তিম"
  },
  State_77692_Desc = {
    Text = "টার্নের শেষে 2টি ডিজলিউশন দানব সমন করো; একই সময়ে সর্বোচ্চ 2টি পর্যন্ত থাকতে পারবে। সমন-করা ডিজলিউশন দানবেরা মারা গেলে, 「ডল: ইনফার্নো」 তার সর্বোচ্চ HP-এর 5% হারায়।"
  },
  State_77692_Name = {
    Text = "অতল দ্বার"
  },
  State_77693_Desc = {
    Text = "মৃত্যুর পর, 「ডল: ইনফার্নো」 5% সর্বোচ্চ HP হারায়।"
  },
  State_77693_Name = {
    Text = "মেল্টডাউন"
  },
  State_78102_Desc = {
    Text = "প্রদত্ত ক্ষতি 15% হ্রাস পায়, এবং প্রাপ্ত ক্ষতি 30% বৃদ্ধি পায়; এটি যুদ্ধের শেষ পর্যন্ত স্থায়ী থাকে।"
  },
  State_78102_Name = {
    Text = "ওভারক্লক পক্ষাঘাত"
  },
  State_78694_Desc = {
    Text = "যুদ্ধের শুরুতে [Arg1] Strength পাও। টার্নের শুরুতে, প্রতি [Arg2] স্থায়ী Strength-এর জন্য [Arg3] অস্থায়ী STR পাও, সর্বোচ্চ [Arg4] অস্থায়ী STR পর্যন্ত; এবং টার্নের শেষে ঐ রেলিক থেকে পাওয়া অস্থায়ী STR-এর অর্ধেক হারাও।"
  },
  State_78696_Desc = {
    Text = "Keyflare Rouse ব্যবহার করার পর, সংশ্লিষ্ট জাগরণকারীর [Arg1]টি 「স্কিল」 বেছে নিয়ে ক্ষয় করো, এবং ক্ষয়সহ [Arg2]টি অনুলিপি ড্র পাইল-এ শাফল করো।"
  },
  State_78697_Desc = {
    Text = "টার্নের শুরুতে, আল্ট্রা স্পেসে প্রতি 1টি ফাঁকা স্থানের জন্য [Arg1] STR অর্জন করুন, তবে [Arg2] স্তর বিষক্রিয়া ভোগ করুন।"
  },
  State_78698_Desc = {
    Text = "অ্যারিথমেটিকা সীমা -[Arg1]। তুমি যখনই [Arg2] বা তার বেশি অ্যারিথমেটিকা ব্যয়যুক্ত কোনো কার্ড খেলো, 1 অ্যারিথমেটিকা পাও। এই প্রভাব প্রতি টার্নে সর্বোচ্চ [Arg3] বার পর্যন্ত সক্রিয় হতে পারে।"
  },
  State_78699_Desc = {
    Text = "ড্র করার পর, অতিরিক্ত [Arg1]টি কার্ড ড্র করো, তবে হাতে থাকা কার্ড থেকে [Arg2]টি কার্ড বেছে ফেলে দাও।"
  },
  State_78700_Desc = {
    Text = "সব জাগরণকারীর মূল ক্ষতি [Arg1]% বৃদ্ধি করো। ডেক যখনই রিসেট হয়, অতিরিক্ত [Arg2]% প্রদান করা হয়, তবে তোমার হাতে একটি 「স্ট্যাগার」 কার্ড যোগ হয়। সর্বোচ্চ বৃদ্ধি [Arg3]%।"
  },
  State_78701_Desc = {
    Text = "টার্ন শুরুর সময়, যদি স্থায়ী শুঁড় [Arg1]-এর বেশি থাকে, তবে [Arg2] শুঁড় হারিয়ে [Arg3] অস্থায়ী শুঁড় লাভ করো; নচেৎ, [Arg4] অস্থায়ী শুঁড় লাভ করো।"
  },
  State_78702_Desc = {
    Text = "কীফ্লেয়ার রাউজ ব্যবহারের পর, অতিরিক্ত [Arg1] কীফ্লেয়ার ব্যয় করো, ফলে প্রাপ্ত রাউজ কার্ডটির অ্যারিথমেটিকা ক্ষয় 0-তে নেমে আসে। তা খেললে, সংশ্লিষ্ট জাগরণের ধারক অতিরিক্ত [Arg2] অ্যালিমাস পায়।"
  },
  State_78703_Desc = {
    Text = "যুদ্ধের শুরুতে, সব শত্রুর ওপর [Arg1] বিষক্রিয়া প্রয়োগ করো। প্রতিটি টার্ন শুরুর আগে, শত্রুর বিষক্রিয়ার [Arg2]% সরিয়ে ফেলো এবং সরানো পরিমাণের [Arg3]% রক্তক্ষরণ হিসেবে প্রয়োগ করো।"
  },
  State_78710_Desc = {
    Text = "প্রতিটি কমান্ড কার্ড খেলার সময়, সংশ্লিষ্ট জাগরণকারীর ঐ টার্নের চূড়ান্ত ক্ষতি [Arg1]% বৃদ্ধি পায়, কিন্তু তারা [Arg2] অ্যালিমাস হারায়। প্রতি টার্নে এই প্রভাব সর্বোচ্চ [Arg3] বার পর্যন্ত সক্রিয় হতে পারে।"
  },
  State_78712_Desc = {
    Text = "রাউন্ড শুরুতে ভ্রূণ সংমিশ্রণ মাত্রা+ [Arg1], আপনার ভ্রূণ রাউন্ড শেষে বাতিল হয়ে যাবে।"
  },
  State_78713_Desc = {
    Text = "টার্নের শুরুতে [Arg1] কাউন্টার লাভ করো। এক টার্নে [Arg2] বার Exalt ব্যবহার করার পর, স্থায়ী কাউন্টার-এর [Arg3]% অপসারণ করো, এবং অপসারিত পরিমাণের [Arg4]% অস্থায়ী কাউন্টার হিসেবে লাভ করো। কুলডাউন: [Arg5] টার্ন।"
  },
  State_78781_Desc = {
    Text = "সাময়িকভাবে লক্ষ্যবস্তুর STR কমাও এবং সমপরিমাণ অস্থায়ী STR অর্জন করো।"
  },
  State_78781_Name = {
    Text = "<TouquKeywords:চুরি>"
  },
  State_79405_Desc = {
    Text = "খেললে, 「স্বচ্ছ স্মৃতি」 1 বৃদ্ধি পায়। 10-এ পৌঁছালে, 1 টার্নের জন্য একে লক করো এবং 3টি 「Insight」 কার্ড পাও; এরপর পরের টার্নের শুরুতে এটি 5-এ রিসেট হবে।"
  },
  State_79405_Name = {
    Text = "প্রকৃত অতীত"
  },
  State_79406_Desc = {
    Text = "খেলার সময়, 「স্বচ্ছ স্মৃতি」 1 কমিয়ে দেয়। 0-তে পৌঁছালে, এক টার্নের জন্য এটিকে লক করো এবং সব অ্যাওয়েকনার 30 অ্যালিমাস অর্জন করে। তারপর পরের টার্নের শুরুতে এটিকে আবার 5-এ রিসেট করো।"
  },
