  State_80052_WeaponDesc = {
    Text = "পরীক্ষা"
  },
  State_80161_Desc = {
    Text = "Team Unique: ধারকের এক্সাল্টের মূল ক্ষতি +<WeaponEffect_Num:[StateArg1]%>, এবং কীফ্লেয়ার পুনর্জাগরণ +<WeaponEffect_Num:[StateArg2]>। আল্ট্রা রাউন্ডে প্রবেশের পর, সব অ্যাওয়েকনার <WeaponEffect_Num:[StateArg4]> অ্যালিমাস পায়। 「বিলয়」 মুক্ত করার পর, ধারক অতিরিক্ত <WeaponEffect_Num:[StateArg3]> অ্যালিমাস অর্জন করে।"
  },
  State_80161_WeaponDesc = {
