  },
  State_80174_Desc = {
    Text = "দলে অনন্য: ধারণকারীর কীফ্লেয়ার পুনর্জন্ম <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়। প্রথম যুদ্ধের শুরুতে, সব শত্রুর ওপর দুর্বলতা এবং ভঙ্গুরতার 1 স্তর সংখ্যা প্রয়োগ করো।"
  },
  State_80174_WeaponDesc = {
    Text = "ধারকের কীফ্লেয়ার পুনর্জন্ম <WeaponEffect_Num:[DescArg1]> দ্বারা বৃদ্ধি পায়। প্রথম যুদ্ধে শুরুর সময়, সব শত্রুর ওপর 1 স্তর করে দুর্বলতা এবং Vulnerable প্রয়োগ করো।"
  },
  State_80207_Desc = {
    Text = "যদি এই কার্ড খেলার পর 「মাত্রা ভ্রমণ」 সক্রিয় হয় তাহলে পরবর্তী প্রভাব সক্রিয় হয়, অতিমাত্রা স্থান থেকে বের করার সময় গণনা শক্তি খরচ -1।"
  },
  State_80207_Name = {
    Text = "<WormholeKeywords:কোয়াসার>"
  },
  State_80328_Desc = {
    Text = "তার আবেগ, বোধ এবং বাকি সবকিছু চিরতরে মৌচাক ইচ্ছাশক্তির সঙ্গে যুক্ত। এই প্রভাব সর্বোচ্চ 15 বার পর্যন্ত স্তরিত হতে পারে। ক্লেমেন্টাইনের এক্সাল্ট 「জীবনরূপ পুনর্গঠন」 দ্বারা 「সহানুভূতি」 ডিবাফ প্রভাবে রূপান্তরিত হতে পারে।"
  },
  State_80328_Name = {
    Text = "মিথোজীবিত্ব"
  },
  State_80331_Desc = {
    Text = "ঝাঁকের ক্ষয়ের নিচে, তোমার দুর্বলতা সম্পূর্ণ উন্মোচিত হয়। এই রাউন্ডে সক্রিয় এবং শুঁড় ক্ষতি বৃদ্ধি [DescArg1]％।"
  },
  State_80331_Name = {
    Text = "<D13Colour:মানসিক আঘাত>"
