    Text = "দলে একমাত্র：সজ্জিতকারী এক্সাল্ট প্রয়োগের পর, এক্সাল্টের মৌলিক ক্ষতি <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়, শিল্ড ও জীবন নিরাময় <WeaponEffect_Num:[StateArg2]%> বৃদ্ধি পায়, সর্বোচ্চ ৫ বার স্তুপ করা যায়। সজ্জিতকারী অন্বেষণে প্রাপ্ত সমসংস্থান হার <WeaponEffect_Num:[StateArg3]%> বৃদ্ধি পায়।"
  },
  State_89555_WeaponDesc = {
    Text = "ধারণকারী এক্সাল্ট মুক্ত করার পর, এক্সাল্ট‑এর মূল ক্ষতি <WeaponEffect_Num:[StateArg1]%> বৃদ্ধি পায়, চরিত্রের ঢাল উৎপাদন এবং HP পুনরুদ্ধার <WeaponEffect_Num:[StateArg2]%> বৃদ্ধি পায়, সর্বোচ্চ 5 বার পর্যন্ত স্তরিত হয়। অনুসন্ধান সমাপ্তির পর, ধারণকারীর প্রাপ্ত সমসংস্থান হার <WeaponEffect_Num:[StateArg3]%> বৃদ্ধি পায়।"
  },
  State_89557_Name = {
    Text = "প্রিজম্যাটিক লেন্স"
  },
  State_89559_Desc = {
    Text = "\n·অস্তিত্বের প্যারাডক্স: অন্বেষণ শুরুতে, মৃত্যু প্রতিরোধের ৭৫％ সর্বোচ্চ জীবনী শক্তি বোনাসে রূপান্তরিত হয়, সর্বোচ্চ ৩০০％ মৃত্যু প্রতিরোধ রূপান্তরিত হতে পারে, সর্বোচ্চ ১০％ সর্বোচ্চ জীবনী শক্তি বৃদ্ধি পায়। প্রতিবার মৃত্যু প্রতিরোধ সক্রিয় হলে অতিরিক্ত ১টি 「রৌপ্য চাবির মৃদু আলো」 হাতে রাখা হয়।\n·অতলান্ত ক্ষতচিহ্ন: বস যুদ্ধে, আমাদের দল যে জীবন নিরাময় পরিমাণ পায় তা প্রতিবার জীবন সীমার ১০০% এ পৌঁছালে, পরবর্তী জীবন নিরাময় প্রভাব ২৫% হ্রাস পায়, কিন্তু বর্তমান মৃত্যু প্রতিরোধের মোট পরিমাণ ২৫% বৃদ্ধি পায়, সর্বোচ্চ ৩ বার সক্রিয় হতে পারে।\n·প্রিজম্যাটিক লেন্স: রাউন্ড শুরুতে, যদি পাল্টা আঘাত জীবন সীমার ২০০০％ ছাড়িয়ে যায়, তাহলে অতিরিক্ত অংশের স্তর সংখ্যা অর্ধেক করা হয়, এবং স্থায়ী পাল্টা আঘাত সর্বোচ্চ ৬০০০％ জীবন সীমা পর্যন্ত স্তুপ করা যায়; যদি শত্রুর বিষক্রিয়া জীবন সীমার ৩০০০％ ছাড়িয়ে যায়, তাহলে অতিরিক্ত অংশের স্তর সংখ্যা অর্ধেক করা হয়, এবং বিষক্রিয়া সর্বোচ্চ ৯০০০％ জীবন সীমা পর্যন্ত স্তুপ করা যায়। জাগরণকারী পাল্টা আঘাত থেকে প্রাপ্ত ক্ষতি বোনাসের পরিমাণ ৭০% হ্রাস পায়, কিন্তু সৃষ্ট সকল বিষক্রিয়া ও পাল্টা আঘাত ১০% বৃদ্ধি পায়। প্রতিটি জাগরণকারীর জাগরণে: রাউন্ড শেষ পরে বর্তমান স্থায়ী পাল্টা আঘাতের ২৫% অস্থায়ী পাল্টা আঘাত অর্জন করা হয়, শত্রু পক্ষের রাউন্ড শেষে সকল শত্রুর ২৫% বিষক্রিয়া অতিরিক্তভাবে সক্রিয় হয়।\n·নিয়তির আলোকশঙ্কু: সাধারণ দানবরা 「দৃষ্টি」 মুক্তি দেওয়ার রাউন্ড সংখ্যা ৬ রাউন্ডে পরিণত হয়। ১৫তম রাউন্ড শুরুতে, ১টি 「আলোক শঙ্কু সীমানা」 হাতে রাখা হয়: S-শক্তি এবং সকল জাগরণকারীর অ্যালিমাস সর্বোচ্চ মানে পূর্ণ করা হয়।"
  },
