  State_89572_Desc = {
    Text = "টার্নের শুরুতে, এলোমেলোভাবে [DescArg1]টি কার্ড <BurningKeywords:Burn> প্রভাবসহ হাতে যোগ করো, এবং [DescArg2] অস্থায়ী শক্তি লাভ করো। প্রতি 2 টার্ন পরপর, যোগ হওয়া জ্বলন্ত কার্ডের সংখ্যা 1 করে বাড়ে, এবং প্রাপ্ত অস্থায়ী শক্তি [DescArg3] করে বৃদ্ধি পায়।"
