  State_89626_Desc = {
    Text = "কীফ্লেয়ার জাগরণ-এর পর, হাতে 1টি 「রৌপ্য চাবির মৃদু আলো」 কার্ড নাও। সব জাগরণকারী জেগে ওঠার পর, প্রতিটি টার্নের শুরুতে এলোমেলো 1টি জাগরণকারীর সহায়তা কার্ড আবিষ্কার করো।"
