  State_89637_Desc = {
    Text = "প্রতিটি টার্নের প্রথম কমান্ড কার্ড অতিরিক্ত একবার কার্যকর হবে। বিনাশের সময় 1টি টেন্টাকল সৃষ্টি করো। টেন্টাকলকে 「রেজিং টাইড」 ভঙ্গিতে বদলানোর পর, এই টার্নে 2টি কমান্ড কার্ডের লীপ প্রভাব অবশ্যই সক্রিয় হবে, আল্ট্রা স্পেসে প্রবেশ করবে; কুলডাউন 3 টার্ন।"
  },
  State_89640_Desc = {
    Text = "রিয়েল্ম দক্ষতা 200 পয়েন্ট বৃদ্ধি পেয়েছে। রক্তিম চুল্লি ভোগ করলে, শুঁড় ডিএমজি 15% বৃদ্ধি পায়। প্রতিটি শুঁড় আক্রমণে [Arg3]টি করে রক্তিম চুল্লি সঞ্চিত করো।"
