  State_89642_Desc = {
    Text = "Hand Limit +2, Exalt-এর পর অস্থায়ী চূড়ান্ত ক্ষতি 10% বৃদ্ধি পায়। কার্ডটি আল্ট্রা স্পেসে প্রবেশ করার পর, হাতে থাকা 1টি 「Embryo」 「পবিত্রতার উত্তরাধিকারী」-তে রূপান্তরিত হয়। প্রতি বার 1টি 「Embryo」 তৈরি হলে, আল্ট্রা স্পেসে থাকা একটি এলোমেলো কার্ডের খরচ 1 কমে যায়।"
